+fn direct_bitlen_update(
+    circ: &mut Circuit,
+    src: &[QReg],
+    peer: &[QReg],
+    lo: usize,
+    target: &[QReg],
+    active: &QReg,
+    selector_gate: &QReg,
+    subtract: bool,
+    extra_lenders: &[&QReg],
+) {
+    let lo = lo.min(src.len().saturating_sub(1));
+    let candidates: Vec<&QReg> = peer
+        .iter()
+        .chain(src.iter())
+        .chain(extra_lenders.iter().copied())
+        .collect();
+    let mut action: Vec<&QReg> = target.iter().collect();
+    action.push(selector_gate);
+    for k in lo..src.len() {
+        for q in &src[k + 1..] {
+            circ.x(q);
+        }
+        let mut selector = Vec::with_capacity(src.len() - k + 1);
+        selector.push(active);
+        selector.push(&src[k]);
+        selector.extend(src[k + 1..].iter());
+        // Materialize the mutually exclusive MSB selector once. Reusing this
+        // borrowed clean gate across the five-bit constant update avoids
+        // rebuilding the long selector for every carry bit.
+        dirty_controlled_x(circ, &selector, selector_gate, &candidates, &action);
+        dirty_controlled_add_const(
+            circ,
+            &[selector_gate],
+            target,
+            k + 1,
+            subtract,
+            &candidates,
+        );
+        dirty_controlled_x(circ, &selector, selector_gate, &candidates, &action);
+        for q in src[k + 1..].iter().rev() {
+            circ.x(q);
+        }
